import Foundation
import Testing

@testable import CloudSync

/// The record itself — and the two places where it could break silently.
@Suite("The cloud record")
struct RecordTests {

    /// **A mirror from before 2026-09-21 must stay readable.**
    ///
    /// ``CloudRecord/encrypted`` was added on that day. The decoding
    /// generated by Swift requires every key — on devices with StoryShelf build 236 the
    /// whole mirror would have become unreadable, and with it the queue: everything that was written without a
    /// network and not yet sent.
    @Test("An old mirror without the field stays readable")
    func oldSnapshot() throws {
        let old = """
            {"typ":"Profileinstellung","name":"theme","geaendert":780000000,
             "felder":{"wert":{"text":{"_0":"indigo"}}}}
            """
        let message = try JSONDecoder().decode(CloudRecord.self, from: Data(old.utf8))
        #expect(message.name == "theme")
        #expect(message["wert"]?.text == "indigo")
        #expect(message.encrypted.isEmpty)
    }

    @Test("A JSON round trip does not lose the secret list")
    func roundTrip() throws {
        let message = CloudRecord(
            contentType: "ChannelList", name: "xtream|a|b", fields: ["secret": .text("password")],
            encrypted: ["secret"])
        let back = try JSONDecoder().decode(
            CloudRecord.self, from: JSONEncoder().encode(message))
        #expect(back == message)
        #expect(back.encrypted == ["secret"])
    }

    /// **The stored form of every field type keeps its German keys.** The cases are English
    /// in code; an old mirror or queue on disk still says `number`, `kommazahl`, `time`,
    /// `wahrheit`, `data`.
    @Test("Old stored field types decode, and new ones encode to the same keys")
    func fieldValueStoredKeys() throws {
        let old = """
            {"typ":"X","name":"n","geaendert":780000000,"felder":{
              "a":{"zahl":{"_0":5}},
              "b":{"kommazahl":{"_0":1.5}},
              "c":{"zeit":{"_0":780000000}},
              "d":{"wahrheit":{"_0":true}},
              "e":{"daten":{"_0":"AQID"}},
              "f":{"text":{"_0":"hi"}}}}
            """
        let record = try JSONDecoder().decode(CloudRecord.self, from: Data(old.utf8))
        #expect(record["a"] == .integer(5))
        #expect(record["b"] == .double(1.5))
        #expect(record["c"] == .date(Date(timeIntervalSinceReferenceDate: 780_000_000)))
        #expect(record["d"] == .bool(true))
        #expect(record["e"] == .data(Data([1, 2, 3])))
        #expect(record["f"] == .text("hi"))

        let encoder = JSONEncoder()
        encoder.outputFormatting = [.sortedKeys]
        let json = String(decoding: try encoder.encode(FieldValue.integer(5)), as: UTF8.self)
        #expect(json == #"{"zahl":{"_0":5}}"#)
        for value in [
            FieldValue.double(2), .date(Date(timeIntervalSinceReferenceDate: 1)), .bool(false),
            .data(Data([9])),
        ] {
            let back = try JSONDecoder().decode(FieldValue.self, from: JSONEncoder().encode(value))
            #expect(back == value)
        }
        let keys = ["kommazahl", "zeit", "wahrheit", "daten"]
        let encoded = [FieldValue.double(2), .date(Date()), .bool(true), .data(Data())]
            .map { String(decoding: (try? JSONEncoder().encode($0)) ?? Data(), as: UTF8.self) }
        for (key, text) in zip(keys, encoded) { #expect(text.hasPrefix("{\"\(key)\":")) }
    }
}
